// Calendar/M&A feeds are global: numeric-leading foreign listing symbols are
// valid provider rows even though C1's requested entry symbols are U.S. names.
const symbolShape=value=>typeof value==='string'&&/^[A-Z0-9][A-Z0-9.&^-]{0,31}$/i.test(value);
// Global earnings calendars include exchange-qualified international tickers
// with internal underscores (observed SALAM_BAH.AE). Preserve their identity;
// this does not change C1's traded universe or quote/account symbol rules.
const earningsSymbolShape=value=>symbolShape(value)||(typeof value==='string'&&value.length<=32&&value.trim()===value&&/^[A-Z0-9]+(?:_[A-Z0-9]+)+\.[A-Z]{1,5}$/i.test(value));
const unresolvedMergerTarget=value=>value===null||value==='_';
const mergerTargetAttribution=row=>!Object.hasOwn(row,'targetedSymbol')?'MISSING':symbolShape(row.targetedSymbol)?'IDENTIFIED':unresolvedMergerTarget(row.targetedSymbol)?'UNATTRIBUTED':'INVALID';
const fingerprint=value=>createHash('sha256').update(JSON.stringify(value)).digest('hex');
function validFeedRow(kind,row,from,to,symbols){
 if(!row||typeof row!=='object'||Array.isArray(row))return false;
 if(kind==='EARNINGS')return earningsSymbolShape(row.symbol)&&validDay(row.date);
 if(kind==='MERGERS')return symbolShape(row.targetedSymbol)||(symbolShape(row.symbol)&&['targetedSymbol','targetedCompanyName','transactionDate','acceptedDate','link'].some(field=>Object.hasOwn(row,field)));
 return symbolShape(row.symbol)&&symbols.has(normalizeSymbol(row.symbol))&&validDay(newsDate(row))&&Boolean(newsText(row));
}
